import{z as l,x as B,o as E,c as A,q as n,j as o,D as t,d as r,s as p,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"per-CPU 数据","description":"","frontmatter":{"title":"per-CPU 数据","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/percpu.md","filePath":"cs/percpu.md","lastUpdated":1791413859000}'),d={name:"cs/percpu.md"};function C(c,e,P,m,u,D){const s=B("Mermaid");return E(),A("div",null,[e[2]||(e[2]=n('<h1 id="per-cpu-数据" tabindex="-1">per-CPU 数据 <a class="header-anchor" href="#per-cpu-数据" aria-label="Permalink to &quot;per-CPU 数据&quot;">​</a></h1><div class="epigraph"><p>每颗 CPU 一份副本，访问时关抢占或用本 CPU 的偏移，于是更新不必与全世界抢同一把锁。</p><footer>—— 据 Love, Linux Kernel Development；Bovet and Cesati 整理</footer></div><p><a href="/cs/kernel-preempt">上一课</a>允许在内核路径中途被切走，也允许被迁移到另一核。全局计数器若每拍都原子加，多核会打同一 cache 行。<a href="/cs/irq-affinity">中断亲和</a>已经把 IRQ 往核上收。缺口是：把统计、缓冲槽、软中断 pending 做成 <strong>per-CPU</strong>——逻辑上一个对象，物理上每核一份。本课只钉这份布局与访问纪律，不引入进程映像。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>共享全局锁保护一个 <code>int</code> 计数，正确但不可扩展。每 CPU 一份：本核读写自己的槽，无需锁，前提是执行期间<strong>不会被抢占到别的核</strong>，或迁移时把「当前 CPU」的寻址做对。缺口不是新的硬中断，而是分配器给出每核偏移，访问用 <code>this_cpu_*</code> 一类原语，并在需要时关抢占。</p><p><span class="marginnote">直觉类比：全局计数像全公司共用一个签到本，人人排队签字；per-CPU 像每人自己口袋里揣个小本，先各记各的，最后再合计。排队没了，代价是「总数」只有在汇总那一刻才知道。</span></p><p><span class="marginnote">读总和要把各 CPU 槽加起来，快照不必瞬间一致；这是统计的代价。要强一致总和，仍得逐核关或用更重的同步。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>启动时为每个 CPU 分配同构的一块：统计、页分配缓存、软中断状态。访问：先关抢占（或已经在 IRQ 上下文、天然不迁移），再按当前 CPU id 取槽。跨核要碰别人的槽时，用 IPI 或接受锁——per-CPU 不是「永远无锁」，只是<strong>本核热路径无锁</strong>。汇总在定时器或 /proc 读取时做。</p>',9)),(E(),o(i,null,{default:t(()=>[p(s,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E9%80%BB%E8%BE%91%E5%AF%B9%E8%B1%A1%22%5D%20--%3E%20C0%5B%22CPU0%20%E6%A7%BD%22%5D%0A%20%20G%20--%3E%20C1%5B%22CPU1%20%E6%A7%BD%22%5D%0A%20%20C0%20--%3E%20LOC%5B%22%E6%9C%AC%E6%A0%B8%E8%AE%BF%E9%97%AE%3A%20%E5%85%B3%E6%8A%A2%E5%8D%A0%22%5D%0A%20%20C1%20--%3E%20LOC2%5B%22%E6%9C%AC%E6%A0%B8%E8%AE%BF%E9%97%AE%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[r(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=a("p",null,[r("与"),a("a",{href:"/cs/paging-vm"},"分页"),r("无关：这是内核虚拟地址里的静态或动态 per-CPU 区，不是用户页表。")],-1)),e[4]||(e[4]=a("p",null,[a("span",{class:"marginnote"},[r("术语翻译："),a("code",null,"this_cpu_*"),r(" 原语就是「取我这一核那份」的快捷指令——它把「查当前 CPU id → 算偏移 → 访问」打包成一条（或在关抢占下几条）操作，省得调用者自己拼。")])],-1)),e[5]||(e[5]=a("h2",{id:"机制",tabindex:"-1"},[r("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[6]||(e[6]=a("p",null,"per-CPU 把锁争用换成迁移纪律。打开内核抢占后，漏了关抢占会在槽 A 上加一半、跑到核 B 再写槽 B，计数撕裂。NMI 若也要记账，槽还须对 NMI 安全，或使用单独的 NMI 计数。软中断 pending 位天然 per-CPU，与上一课的上下文模型一致。",-1)),(E(),o(i,null,{default:t(()=>[p(s,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20TD%0A%20%20A%5B%22%E6%A0%B8%20A%20%E4%B8%8A%E6%9B%B4%E6%96%B0%E8%87%AA%E5%B7%B1%E7%9A%84%E6%A7%BD%22%5D%20--%3E%20B%7B%22%E4%B8%AD%E9%80%94%E8%A2%AB%E6%8A%A2%E5%8D%A0%E5%B9%B6%E8%BF%81%E7%A7%BB%3F%22%7D%0A%20%20B%20--%3E%7C%E5%90%A6%7C%20OK%5B%22%E6%A7%BD%20A%20%E8%AE%A1%E6%95%B0%E5%AE%8C%E6%95%B4%22%5D%0A%20%20B%20--%3E%7C%E6%98%AF%7C%20C%5B%22%E4%BB%BB%E5%8A%A1%E8%B7%91%E5%88%B0%E6%A0%B8%20B%22%5D%0A%20%20C%20--%3E%20D%5B%22%E5%86%8D%E5%8F%96%E5%BD%93%E5%89%8D%20CPU%20%E6%8B%BF%E5%88%B0%E6%A7%BD%20B%22%5D%0A%20%20D%20--%3E%20E%5B%22%E4%B8%80%E6%AC%A1%E4%BA%8B%E4%BB%B6%E6%8B%86%E4%B8%A4%E5%8D%8A%3A%20A%20%E8%AE%B0%E5%8D%8A%E6%88%AA%20B%20%E8%AE%B0%E5%8D%8A%E6%88%AA%22%5D%0A"})]),fallback:t(()=>[...e[1]||(e[1]=[r(" Loading... ",-1)])]),_:1})),e[7]||(e[7]=n('<p>后课的进程是跨 CPU 迁移的对象；它的 PCB 不是 per-CPU 的。本课只把「核本地内核状态」交出去。</p><p><span class="marginnote">数字实例：64 核每秒各做 100 万次计数。走全局原子加，就是每秒 6400 万次跨核缓存行乒乓；换成 per-CPU，核内是普通加法，汇总每秒只做一次。撕裂 bug 则更阴险——总数只是悄悄偏小，通常不报错。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把所有 <code>DEFINE_PER_CPU</code> 变量列清单，不写 false sharing 的缓存行对齐微优化全书。用户态的线程局部存储是更后的 TLS 课，对象是进程内线程，不是 CPU。</p><p>后课默认：内核统计与核本地队列可以无锁。内核要切换的<strong>用户状态包</strong>叫什么、里面有什么，下一课讲<a href="/cs/process-image">进程映像</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>per-CPU：每核一份，本核热路径免全局锁。</li><li>访问须关抢占或处于不迁移上下文。</li><li>用户进程映像是下一课，不是 per-CPU 对象。</li><li>出处：Love, <em>LKD</em>；Bovet and Cesati。</li></ul>',7))])}const U=l(d,[["render",C]]);export{f as __pageData,U as default};
